memberdef.definition:
using themis::updates::CoordinatedUpdateManager::WaitForPreviousFunc = 
std::function<bool(const std::string& prev_node_id,
                   std::chrono::milliseconds timeout)>

detaileddescription.para:
Usage example: CoordinatedUpdateConfigcfg;
cfg.version="1.7.0";
cfg.local_node_id=hostname;
cfg.nodes={{"node-a",0,false},
{"node-b",1,false},
{"node-c",2,true}};//node-cisleader

CoordinatedUpdateManagermgr(hot_reload_engine,cfg);

mgr.setWaitForPreviousFunc([&](conststd::string&prev_id,
std::chrono::millisecondstimeout){
returncluster_bus.waitForNodeReady(prev_id,timeout);
});
mgr.setSignalReadyFunc([&](conststd::string&local_id,boolok){
cluster_bus.signalReady(local_id,ok);
});

autoresult=mgr.applyLocalUpdate();
if(!result.success){
LOG_ERROR("Coordinatedupdatefailed:{}",result.error_message);
}
